
import React, { useState, useEffect } from "react";


import {   DropDwnSearchPicker_Cmpt } from "../../../components";
import {  	fetchEncryptStream, getStore, ObjectKeys,  qryKprofile,  qryStore,  txtOrempty,  } from "../../../stores/Utils";


const DropDwnSearchPicker = DropDwnSearchPicker_Cmpt();






 
const PickProductAsync  = ({ init, emptyLabel, onSelect, exFlds }) => {

	const [list, setList] = useState([]);

	const parseD =  (v) => {
		let nA = []
		v && ObjectKeys(v).map(cl=>{
			let fullNm = txtOrempty(v[cl]?.firstName) + txtOrempty(v[cl]?.middleName)  + txtOrempty(v[cl]?.lastName);
			nA.push({id:cl, label: fullNm, data: v[cl] });
		})
		setList(nA);
	}

	const fetch = async (v) => {
		let dt = await search_notary_cl(v, exFlds);
		parseD(dt)
	}

	const clear =  () => {
		setList([]);
	}


	return (
		<div style={{minWidth: 260}}>
			<DropDwnSearchPicker
				lbl_empty={init || emptyLabel} 
				list={list}
				onSelect={(e)=>onSelect(e)} 
				background={"var(--hrm_palette-general-background-b)"}
				color={"var(--light-200)"}
				callempty={clear}
				fetchData={fetch}
			/>
		</div>
	)

}



export default PickProductAsync;




const search_notary_cl = async (search,extraFields ) => {
    if(search.length>2){
       
		let bdyq2 = {...getStore(qryStore())?.search_prod};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			limit: 120,
			year: getStore("date_current_year")
		}
		bdyq2.extraFields = extraFields;


        search.split(" ").map((qry,inDq)=>{
            if(qry){
                bdyq2.params[":search"+inDq] = qry.trim();
            }
        });
       
        bdyq2.params[":search5"] = getStore(qryKprofile())?.businessId;
        
        const res = fetchEncryptStream(bdyq2);
        const td = await res;
        if (td && !td.error) {
            return td
        }
    }
   
    return null;
    
};